// "JANE BROKER" -> "Jane Broker", "PRIVATE BANK" -> "Private Bank"
// Only converts when the ENTIRE string is uppercase (won't touch "McDonald" or "De La Cruz")
function toTitleCase(str) {
  if (!str || str.length < 2) return str;
